   284→    // Tension based on: raw numbers, speed of influx, economic conditions, social stability
   285→    const popRatio = state.humanPopulationSystem.population * 1000; // Convert to millions
   286→    const displacementScale = crisis.currentlyDisplaced / popRatio; // Ratio
   287→    const influxSpeed = crisis.monthsActive < 12 ? 1.5 : 1.0; // Recent = higher tension
