   293→    );
   294→
   295→    // === CALCULATE ECONOMIC STRAIN ===
   296→    // Cost: $2,000 per refugee per year = $166/month
   297→    const monthlyCostPerRefugee = 166 / 1000000; // In millions
   298→    const totalCost = crisis.currentlyDisplaced * monthlyCostPerRefugee;
   299→    crisis.economicStrain = totalCost / 1000; // Fraction of ~$100T global GDP
   300→
