                    <option value="opt-moderate">Moderate Priority (20%) - Biden/EU</option>
                    <option value="opt-ambitious">Ambitious Priority (35%) - Denmark</option>
                    <option value="opt-crisis">Crisis Mode (45%) - Wartime</option>
