   298→      `   Difference:   ${populationDiff.toFixed(3)}B (${(populationDiff / globalPopulation * 100).toFixed(2)}%)\n` +
   299→      `   Month:        ${state.currentMonth}`
   300→    );
   301→  }
   302→
   303→  // === CARRYING CAPACITY CONSISTENCY ===
   304→  const regionalCapacitySum = regions.reduce((sum, r) => sum + r.carryingCapacity, 0);
   305→  const globalCapacity = state.humanPopulationSystem.carryingCapacity;
   306→  const capacityDiff = Math.abs(regionalCapacitySum - globalCapacity);
   307→
