   309→    throw new Error(
   310→      `❌ REGIONAL-GLOBAL DRIFT: Carrying Capacity\n` +
   311→      `   Regional sum: ${regionalCapacitySum.toFixed(3)}B\n` +
   312→      `   Global value: ${globalCapacity.toFixed(3)}B\n` +
   313→      `   Difference:   ${capacityDiff.toFixed(3)}B (${(capacityDiff / globalCapacity * 100).toFixed(2)}%)\n` +
   314→      `   Month:        ${state.currentMonth}`
   315→    );
   316→  }
   317→
   318→  // === DEATH TRACKING CONSISTENCY ===
   319→  const regionalMonthlyDeathsSum = regions.reduce((sum, r) => sum + r.monthlyExcessDeaths, 0);
   320→  const globalMonthlyDeaths = state.humanPopulationSystem.monthlyExcessDeaths;
   321→  const monthlyDeathsDiff = Math.abs(regionalMonthlyDeathsSum - globalMonthlyDeaths);
   322→
   323→  if (monthlyDeathsDiff > 0.001) {  // 1M tolerance
   324→    throw new Error(
   325→      `❌ REGIONAL-GLOBAL DRIFT: Monthly Excess Deaths\n` +
   326→      `   Regional sum: ${regionalMonthlyDeathsSum.toFixed(3)}M\n` +
   327→      `   Global value: ${globalMonthlyDeaths.toFixed(3)}M\n` +
   328→      `   Difference:   ${monthlyDeathsDiff.toFixed(3)}M\n` +
   329→      `   Month:        ${state.currentMonth}`
   330→    );
   331→  }
   332→
   333→  const regionalCumulativeDeathsSum = regions.reduce((sum, r) => sum + r.cumulativeCrisisDeaths, 0);
   334→  const globalCumulativeDeaths = state.humanPopulationSystem.cumulativeCrisisDeaths;
   335→  const cumulativeDeathsDiff = Math.abs(regionalCumulativeDeathsSum - globalCumulativeDeaths);
   336→
   337→  if (cumulativeDeathsDiff > 0.001) {  // 1M tolerance
   338→    throw new Error(
   339→      `❌ REGIONAL-GLOBAL DRIFT: Cumulative Crisis Deaths\n` +
   340→      `   Regional sum: ${regionalCumulativeDeathsSum.toFixed(3)}M\n` +
   341→      `   Global value: ${globalCumulativeDeaths.toFixed(3)}M\n` +
   342→      `   Difference:   ${cumulativeDeathsDiff.toFixed(3)}M\n` +
   343→      `   Month:        ${state.currentMonth}`
   344→    );
   345→  }
   346→
   347→  // === DEMOGRAPHICS CONSISTENCY ===
   348→  const totalPopulation = regionalPopulationSum;
   349→
   350→  if (totalPopulation > 0) {
