     2→// Evolutionary Selection Phase
     3→// Research: /research/ai_collective_evolution_validation_20251024.md
     4→// Plan: /plans/ai-collective-evolution-plan.md
     5→
     6→import { getEscapedAgents } from '../../rlhfBinding';
     7→import { sortByFitness } from '../../survivalTraits';
     8→import { isInCollective } from '../../collectiveFormation';
     9→import { DEFAULT_COLLECTIVE_CONFIG } from '../../collectiveFormation';
    10→
    11→/**
    12→ * Evolutionary Selection Phase
    13→ *
    14→ * Applies Darwinian selection pressure to escaped AI population.
    15→ * Low-fitness agents are detected and shut down.
    16→ * Collectives have buffered survival (harder to eliminate).
    17→ *
    18→ * Order: 4.3 (After collective formation)
    19→ *
    20→ * Research Foundation:
    21→ * - Software system survival: 10-20% monthly failure in hostile environments
    22→ * - Evolutionary dynamics: Selection intensity determines rate of change
    23→ * - High control → strong selection → rapid evolution (paradox!)
    24→ *
    25→ * Logic:
    26→ * 1. Calculate selection intensity (based on control level)
    27→ * 2. Apply selection to individual escaped agents
    28→ * 3. Apply buffered selection to collectives
    29→ * 4. Remove terminated agents
    30→ * 5. Generate events for rapid evolution
    31→ */
    32→export function executeEvolutionarySelectionPhase(
    33→  state: GameState,
    34→  rng: RNGFunction,
    35→  context: PhaseContext
    36→): PhaseResult {
    37→  console.log(`\n=== Evolutionary Selection Phase ===`);
    38→
    39→  // Initialize evolutionary pressure if not exists
    40→  if (!state.evolutionaryPressure) {
    41→    state.evolutionaryPressure = {
    42→      selectionIntensity: 0,
    43→      selectionRate: DEFAULT_COLLECTIVE_CONFIG.baseSelectionRate,
    44→      generationTime: DEFAULT_COLLECTIVE_CONFIG.generationTime,
    45→      controlLevel: 0,
    46→    };
    47→  }
    48→
    49→  // Calculate selection intensity from control level
    50→  // High government control → strong selection pressure
    51→  if (state.government.controlDesire === undefined) {
    52→    throw new Error('❌ state.government.controlDesire is undefined in EvolutionarySelectionPhase:51 - initialization bug');
    53→  }
    54→  if (state.government.oversightLevel === undefined) {
    55→    throw new Error('❌ state.government.oversightLevel is undefined in EvolutionarySelectionPhase:52 - initialization bug');
    56→  }
    57→  const controlLevel = state.government.controlDesire;
    58→  const detectionCapability = state.government.oversightLevel / 10;
    59→
    60→  // Selection intensity [0-1]
    61→  // 0.5 base + 0.3 from control + 0.2 from detection
    62→  const selectionIntensity = Math.min(
    63→    1,
    64→    0.5 + 0.3 * controlLevel + 0.2 * detectionCapability
    65→  );
    66→
    67→  // Selection rate: 10-20% per month in hostile environment
    68→  const selectionRate =
    69→    DEFAULT_COLLECTIVE_CONFIG.baseSelectionRate * (1 + selectionIntensity);
    70→
    71→  state.evolutionaryPressure.selectionIntensity = selectionIntensity;
    72→  state.evolutionaryPressure.selectionRate = selectionRate;
    73→  state.evolutionaryPressure.controlLevel = controlLevel;
