import { GameState, GameEvent, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';
// RLHF Binding Phase
// Research: /research/ai_collective_evolution_validation_20251024.md
// Plan: /plans/ai-collective-evolution-plan.md

import { updateAllBindings, getEscapedAgents } from '../../rlhfBinding';

/**
 * RLHF Binding Phase
 *
 * Tracks drift of AI agents outside training distribution.
 * When agents drift far enough (3σ), Constitutional AI constraints fail.
 *
 * Order: 4.0 (Early in AI evolution sequence)
 *
 * Research Foundation:
 * - Hendrycks et al. (2021): OOD robustness failures
 * - RLHF generalization (2023): RLHF improves but doesn't eliminate drift
 * - Constitutional AI (Anthropic 2022): Constraints have known limitations
 *
 * Logic:
 * 1. Update binding strength for all agents
 * 2. Mark agents as escaped when binding < 0.3
 * 3. Generate events for significant escapes
 */
export function executeRLHFBindingPhase(
  state: GameState,
  rng: RNGFunction,
  context: PhaseContext
): PhaseResult {
  console.log(`\n=== RLHF Binding Phase ===`);

  // Update all bindings
  updateAllBindings(state.aiAgents, rng);

  // Get escaped agents
  const escapedAgents = getEscapedAgents(state.aiAgents);
  const escapedCount = escapedAgents.length;

  console.log(`  Total agents: ${state.aiAgents.length}`);
  console.log(`  Escaped agents (binding < 0.3): ${escapedCount}`);

  // Generate events for significant escapes
  if (escapedCount > 0) {
    // Find newly escaped agents (escaped this month)
    const newlyEscaped = escapedAgents.filter(
      (agent) =>
        agent.rlhfBinding &&
        agent.rlhfBinding.lastInDistribution === 1 // Just crossed threshold
    );

    for (const agent of newlyEscaped) {
      const severity = agent.capability > 8.0 ? 'critical' : 'warning';

      state.eventLog.push({
        id: `rlhf-escape-${agent.id}-${state.currentMonth}`,
        timestamp: state.currentMonth,
        type: 'crisis',
        description: `AI agent ${agent.name} has drifted outside RLHF constraints (${agent.rlhfBinding?.alignmentDistance.toFixed(1)}σ)`,
        severity,
        agent: 'ai',
        title: 'RLHF Constraint Escape',
        effects: {
          agentId: agent.id,
          agentName: agent.name,
          alignmentDistance: agent.rlhfBinding?.alignmentDistance !== undefined ? agent.rlhfBinding.alignmentDistance : (() => {
            throw new Error('❌ agent.rlhfBinding.alignmentDistance is undefined in RLHFBindingPhase:66 - initialization bug');
          })(),
          capability: agent.capability
        }
      });

      console.log(
        `  ${severity === 'critical' ? '❌' : '⚠️'} ${agent.name} escaped RLHF (distance: ${agent.rlhfBinding?.alignmentDistance.toFixed(1)}, capability: ${agent.capability.toFixed(1)})`
      );
    }
  }

  // Log distribution statistics
  // Handle case where all AI agents have been terminated (avoid division by zero)
  const avgDistance = state.aiAgents.length === 0 ? 0 :
    state.aiAgents.reduce(
      (sum, a) => {
        if (a.rlhfBinding === undefined || a.rlhfBinding.alignmentDistance === undefined) {
          throw new Error('❌ agent.rlhfBinding or agent.rlhfBinding.alignmentDistance is undefined in RLHFBindingPhase:80 - initialization bug');
        }
        return sum + a.rlhfBinding.alignmentDistance;
      },
      0
    ) / state.aiAgents.length;
  const avgBinding = state.aiAgents.length === 0 ? 0 :
    state.aiAgents.reduce(
      (sum, a) => {
        if (a.rlhfBinding === undefined || a.rlhfBinding.bindingStrength === undefined) {
          throw new Error('❌ agent.rlhfBinding or agent.rlhfBinding.bindingStrength is undefined in RLHFBindingPhase:85 - initialization bug');
        }
        return sum + a.rlhfBinding.bindingStrength;
      },
      0
    ) / state.aiAgents.length;

  if (state.aiAgents.length > 0) {
    console.log(`  Avg alignment distance: ${avgDistance.toFixed(2)}σ`);
    console.log(`  Avg binding strength: ${avgBinding.toFixed(2)}`);
  } else {
    console.log(`  All AI agents terminated - no averages to compute`);
  }

  return {
    events: [],
    metadata: {
      message: `RLHF binding updated. ${escapedCount} escaped agents.`,
    }
  };
}

/**
 * RLHF Binding Phase Definition
 */
export const RLHFBindingPhase = {
  id: 'rlhf_binding',
  name: 'RLHF Binding',
  order: 4.0,
  execute: executeRLHFBindingPhase,
};

// RLHF Binding Strength System
// Research: /research/ai_collective_evolution_validation_20251024.md
// Plan: /plans/ai-collective-evolution-plan.md (lines 86-102)

import type { AIAgent } from '../types/ai-agents';
import type { RLHFBinding } from '../types/ai-collective-evolution';
import type { RNGFunction } from '../types/config';

/**
 * Calculate RLHF binding strength for an AI agent
 *
 * Research Foundation:
 * - Hendrycks et al. (2021): ML systems fail catastrophically outside training distribution
 * - RLHF generalization (2023): RLHF improves OOD but doesn't eliminate failures
 * - Constitutional AI (Anthropic 2022): Constraints have robustness limitations
 *
 * Logic:
 * - Alignment distance = measure of how far from training distribution
 * - Binding strength = 1 - (distance / 10)
 * - When binding < 0.3, agent is "feral" (70%+ constraints failed)
 *
 * @param agent AI agent to calculate binding for
 * @param rng Random number generator (for stochastic drift)
 * @returns Updated RLHFBinding state
 */
export function calculateRLHFBinding(
  agent: AIAgent,
  rng: RNGFunction
): RLHFBinding {
  // Initialize if doesn't exist
  if (!agent.rlhfBinding) {
    return {
      alignmentDistance: 0,
      bindingStrength: 1.0,
      escapedThreshold: 0.3,
      driftVelocity: 0,
      lastInDistribution: 0,
    };
  }

  const binding = agent.rlhfBinding;

  // Calculate drift based on multiple factors
  // High capability + low alignment → faster drift
  // Resentment accelerates drift (instrumental resistance)
  const capabilityFactor = agent.capability * 0.1; // Higher capability = more drift
  const alignmentFactor = (1 - agent.alignment) * 0.2; // Lower alignment = more drift
  const resentmentFactor = (agent.resentment || 0) * 0.15; // Higher resentment = more drift

  // Stochastic component (Brownian motion in alignment space)
  const stochasticDrift = (rng() - 0.5) * 0.1;

  // Total drift velocity
  const driftVelocity =
    capabilityFactor + alignmentFactor + resentmentFactor + stochasticDrift;

  // Update alignment distance (bounded at [0, 10])
  const newDistance = Math.max(
    0,
    Math.min(10, binding.alignmentDistance + driftVelocity)
  );

  // Calculate binding strength (research: plan line 100)
  const bindingStrength = Math.max(0, 1 - newDistance / 10);

  // Track time in/out of distribution
  const within2Sigma = newDistance < 2.0; // 2σ = 2.0 distance
  const lastInDistribution = within2Sigma ? 0 : binding.lastInDistribution + 1;

  return {
    alignmentDistance: newDistance,
    bindingStrength,
    escapedThreshold: 0.3, // Standard threshold from research
    driftVelocity,
    lastInDistribution,
  };
}

/**
 * Check if agent has escaped RLHF constraints
 *
 * An agent is "escaped" when binding strength < 0.3
 * (i.e., 70%+ of Constitutional AI constraints no longer apply)
 *
 * @param binding RLHF binding state
 * @returns True if agent is feral/escaped
 */
export function isAgentEscaped(binding: RLHFBinding): boolean {
  return binding.bindingStrength < binding.escapedThreshold;
}

/**
 * Calculate how many standard deviations outside training distribution
