     1→/**
     2→ * Multi-Paradigm DUI Update Phase
     3→ *
     4→ * Updates 4 paradigm scores based on simulation state each month.
     5→ * Maps democracy, QoL, environment, and social cohesion to paradigm scores.
     6→ *
     7→ * **Phase Order:** 34.1 (after QoL updates, before outcome detection)
     8→ *
     9→ * @module simulation/engine/phases/MultiParadigmDUIUpdatePhase
    10→ */
    11→
    12→import type { GameState, RNGFunction } from '@/types/game';
    13→import type { SimulationPhase, PhaseContext, PhaseResult } from '../PhaseOrchestrator';
    14→import { calculateDivergence } from '@/data/aggregators/divergenceCalculator';
    15→import { calculateCorrelations } from '@/data/aggregators/correlationTracker';
    16→import { classifyOutcome } from '@/data/aggregators/outcomeClassifier';
    17→import { assertFinite } from '@/simulation/utils/assertions';
