    19→/**
    20→ * Multi-Paradigm DUI Update Phase
    21→ *
    22→ * Updates paradigm scores based on simulation state.
    23→ */
    24→export class MultiParadigmDUIUpdatePhase implements SimulationPhase {
    25→  readonly id = 'multi_paradigm_dui_update';
    26→  readonly name = 'Multi-Paradigm DUI Update';
    27→  readonly order = 34.1;
    28→
    29→  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult {
    30→    // Calculate new paradigm scores from simulation state
    31→    const scores = calculateParadigmScoresFromState(state);
    32→
    33→    // Debug logging for first month
    34→    if (state.currentMonth === 0) {
    35→      console.log(`🌍 MultiParadigm Month 0: W=${scores.western.toFixed(1)}, D=${scores.development.toFixed(1)}, E=${scores.ecological.toFixed(1)}, I=${scores.indigenous.toFixed(1)}`);
    36→      console.log(`   democracy exists: ${!!state.government.democracy}, socialCohesion exists: ${!!state.socialAccumulation?.socialCohesion}`);
    37→    }
    38→
    39→    // Update paradigm scores
    40→    state.multiParadigmDUI.paradigmScores.western.value = scores.western;
    41→    state.multiParadigmDUI.paradigmScores.development.value = scores.development;
    42→    state.multiParadigmDUI.paradigmScores.ecological.value = scores.ecological;
    43→    state.multiParadigmDUI.diagnosticLenses.indigenous.value = scores.indigenous;
    44→
    45→    // Add to history
    46→    state.multiParadigmDUI.history.push({
    47→      month: state.currentMonth,
    48→      western: scores.western,
    49→      development: scores.development,
    50→      ecological: scores.ecological,
    51→      indigenous: scores.indigenous,
    52→    });
    53→
    54→    // Calculate divergence (with trend detection if enough history)
    55→    state.multiParadigmDUI.divergence = calculateDivergence(scores, state.multiParadigmDUI.history);
    56→
    57→    // Calculate outcome classification
    58→    state.multiParadigmDUI.outcome = classifyOutcome(scores);
    59→
    60→    // Legacy DUI removed - use multiParadigmDUI directly instead
    61→    // (dystopiaUtopiaIndex no longer exists in GlobalMetrics)
    62→
    63→    return {
    64→      events: [], // PhaseResult.events expects GameEvent[], not string[]
    65→    };
    66→  }
    67→}
