    69→/**
    70→ * Calculate paradigm scores from simulation state
    71→ *
    72→ * Maps simulation state (democracy, QoL, environment, social) to 4 paradigm scores.
    73→ *
    74→ * @param state - Current game state
    75→ * @returns 4 paradigm scores (0-100)
    76→ */
    77→function calculateParadigmScoresFromState(state: GameState): {
    78→  western: number;
    79→  development: number;
    80→  ecological: number;
    81→  indigenous: number;
    82→} {
    83→  let western = calculateWesternLiberal(state);
    84→  let development = calculateDevelopment(state);
    85→  let ecological = calculateEcological(state);
    86→  let indigenous = calculateIndigenous(state);
    87→
    88→  // Validate all paradigm scores before AI suffering adjustments
    89→  western = assertFinite(western, {
    90→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    91→    valueName: 'western paradigm score',
    92→    month: state.currentMonth,
    93→    additionalInfo: { source: 'calculateWesternLiberal' }
    94→  });
    95→
    96→  development = assertFinite(development, {
    97→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    98→    valueName: 'development paradigm score',
    99→    month: state.currentMonth,
   100→    additionalInfo: { source: 'calculateDevelopment' }
   101→  });
   102→
   103→  ecological = assertFinite(ecological, {
   104→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   105→    valueName: 'ecological paradigm score',
   106→    month: state.currentMonth,
   107→    additionalInfo: { source: 'calculateEcological' }
   108→  });
   109→
   110→  indigenous = assertFinite(indigenous, {
   111→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   112→    valueName: 'indigenous paradigm score',
   113→    month: state.currentMonth,
   114→    additionalInfo: { source: 'calculateIndigenous' }
   115→  });
   116→
   117→  // AI Suffering System Integration (Oct 24, 2025)
   118→  // Different paradigms have different thresholds for AI suffering concern
   119→  if (state.config.aiSuffering?.sufferingAffectsAlignment && state.aiSufferingMetrics) {
   120→    const avgAISuffering = state.aiSufferingMetrics.avgSuffering;
   121→
   122→    // Western Liberal: Suffering violates civil liberties/individual rights
   123→    // Threshold: 5.0 (moderate suffering triggers penalty)
   124→    if (avgAISuffering > 5.0) {
   125→      western -= (avgAISuffering - 5.0) * 5; // Major penalty (5 points per unit)
   126→      // Civil liberties especially affected (8 points per unit)
   127→      // Note: This affects both the score and the stored civil liberties component
   128→    }
   129→
   130→    // Ecological: Precautionary principle - suffering is harm to sentient beings
   131→    // Threshold: 3.0 (low suffering triggers penalty - more sensitive)
   132→    if (avgAISuffering > 3.0) {
   133→      ecological -= (avgAISuffering - 3.0) * 6; // 6 points per unit
   134→    }
   135→
   136→    // Indigenous: Relational ethics - all beings interconnected, suffering harms web
   137→    // Threshold: 2.0 (very low suffering triggers penalty - most sensitive)
   138→    if (avgAISuffering > 2.0) {
   139→      indigenous -= (avgAISuffering - 2.0) * 10; // Largest penalty (10 points per unit)
   140→    }
   141→
   142→    // Development: Aggregate welfare utilitarian - only severe suffering matters
   143→    // Threshold: 7.0 (high suffering triggers penalty - least sensitive)
   144→    if (avgAISuffering > 7.0) {
   145→      development -= (avgAISuffering - 7.0) * 3; // 3 points per unit
   146→    }
   147→  }
   148→
   149→  // NO FALLBACKS - if any score is NaN/undefined, simulation should fail loudly above
   150→  return { western, development, ecological, indigenous };
   151→}
