   153→/**
   154→ * Calculate Western Liberal paradigm score from simulation state
   155→ *
   156→ * **SCORING REDESIGN (Oct 21, 2025):** Expose component scores instead of compressing into geometric mean.
   157→ * Geometric mean invokes Goodhart's Law - when one component collapses, headline number obscures nuance.
   158→ *
   159→ * Indicators (now tracked separately):
   160→ * - Electoral Democracy (40%): state.government.democracy.electoralDemocracyIndex (0-100)
   161→ * - Civil Liberties (30%): state.socialCohesion.civilLiberties (0-100)
   162→ * - Rule of Law (20%): state.government.democracy.ruleOfLaw (0-100)
   163→ * - Economic Freedom (10%): 100 - state.government.economicPolicy.marketRegulation (0-100)
   164→ *
   165→ * Components stored in state.multiParadigmDUI.westernLiberalComponents for analysis.
   166→ *
   167→ * @param state - Current game state
   168→ * @returns Western Liberal score (0-100) - STILL geometric mean for backward compatibility, but components tracked
   169→ */
   170→function calculateWesternLiberal(state: GameState): number {
   171→  const MIN_FLOOR = 0.1;
   172→
   173→  // Electoral Democracy (0-1 → 0-100)
   174→  if (state.government.democracy === undefined) {
   175→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:149 - initialization bug');
   176→  }
   177→  const electoralDemocracy = state.government.democracy * 100;
   178→
   179→  // Civil Liberties (0-100)
   180→  if (state.socialAccumulation?.socialCohesion?.civilLiberties === undefined) {
   181→    throw new Error('❌ state.socialAccumulation.socialCohesion.civilLiberties is undefined in calculateWesternLiberal:152 - initialization bug');
   182→  }
   183→  const civilLiberties = state.socialAccumulation.socialCohesion.civilLiberties;
   184→
   185→  // Rule of Law (0-100) - use democracy as proxy if specific property not available
   186→  if (state.government.democracy === undefined) {
   187→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:155 - initialization bug');
   188→  }
   189→  const ruleOfLaw = state.government.democracy * 100;
   190→
   191→  // Economic Freedom (inverted market regulation) - default to moderate
   192→  const economicFreedom = 50;
   193→
   194→  // STORE COMPONENTS for decomposed analysis (avoiding Goodhart's Law)
   195→  if (!state.multiParadigmDUI.westernLiberalComponents) {
   196→    state.multiParadigmDUI.westernLiberalComponents = [];
   197→  }
   198→
   199→  state.multiParadigmDUI.westernLiberalComponents.push({
   200→    month: state.currentMonth,
   201→    electoralDemocracy,
   202→    civilLiberties,
   203→    ruleOfLaw,
   204→    economicFreedom,
   205→  });
   206→
   207→  // Geometric mean (non-compensatory) - KEPT for backward compatibility
   208→  // BUT: Users should analyze components, not this headline number
   209→  const indicators = [electoralDemocracy, civilLiberties, ruleOfLaw, economicFreedom];
   210→
   211→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   212→  for (let i = 0; i < indicators.length; i++) {
   213→    if (isNaN(indicators[i])) {
   214→      console.error(`❌ NaN in Western Liberal indicator ${i} at month ${state.currentMonth}`);
   215→      console.error(`   electoralDemocracy: ${electoralDemocracy}`);
   216→      console.error(`   civilLiberties: ${civilLiberties}`);
   217→      console.error(`   ruleOfLaw: ${ruleOfLaw}`);
   218→      console.error(`   economicFreedom: ${economicFreedom}`);
   219→      throw new Error(`NaN in Western Liberal paradigm calculation - indicator ${i} is NaN`);
   220→    }
   221→  }
   222→
   223→  const product = indicators.reduce((acc, val) => {
   224→    const floored = Math.max(val, MIN_FLOOR);
   225→    return acc * (floored / 100);
   226→  }, 1);
   227→
   228→  const result = Math.pow(product, 1 / indicators.length) * 100;
   229→
   230→  // Final NaN check - if this triggers, something is wrong with the calculation itself
   231→  if (isNaN(result)) {
   232→    console.error(`❌ NaN result in Western Liberal calculation at month ${state.currentMonth}`);
   233→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   234→    throw new Error(`Western Liberal geometric mean produced NaN - check calculation`);
   235→  }
   236→
   237→  return result;
   238→}
