   320→/**
   321→ * Calculate Ecological paradigm score from simulation state
   322→ *
   323→ * UPDATED (Oct 21, 2025 - FIX #14): Uses progressive recovery scoring system
   324→ * - Replaces binary breach counting with impact-weighted recovery progress
   325→ * - Gives credit for partial recovery before full boundary un-breach
   326→ * - Research-backed weights based on mortality potential
   327→ *
   328→ * Indicators:
   329→ * - Planetary Boundaries (50%): Progressive recovery score (0-100)
   330→ * - Resource Depletion (25%): 100 - resourceDepletion
   331→ * - Climate Stability (15%): 100 - (temperatureAnomaly / 2.0) * 100
   332→ * - Pollution (10%): 100 - pollutionLevel
   333→ *
   334→ * SCORE INTERPRETATION (Empirically Realistic, FIX #14):
   335→ * - **0-10 (Catastrophic Collapse):**
   336→ *     Most/all boundaries breached, cascades active, mass mortality
   337→ *     Expected frequency: 15-25% of runs
   338→ *
   339→ * - **10-30 (Stabilized):**
   340→ *     Boundaries still breached but not worsening, technologies deployed,
   341→ *     emissions declining but ecosystem damage persists
   342→ *     Expected frequency: 40-50% of runs (MOST REALISTIC OUTCOME)
   343→ *     This is NOT dystopia - represents sustainable development path
   344→ *
   345→ * - **30-60 (Recovering):**
   346→ *     Some boundaries un-breached, partial restoration underway,
   347→ *     sustained net-negative emissions, slow healing
   348→ *     Expected frequency: 25-35% of runs
   349→ *     Requires 10-30 years sustained action post-net-zero
   350→ *
   351→ * - **60-100 (Restored):**
   352→ *     Most boundaries safe, ecosystem resilience restored,
   353→ *     full environmental health achieved
   354→ *     Expected frequency: 5-10% of runs (HEROIC ACTION + 50-100 YEARS)
   355→ *     Requires 50-100 years sustained effort beyond simulation timeframe
   356→ *
   357→ * CRITICAL: 10-30/100 is NOT failure - it's empirically realistic stabilization.
   358→ * Full restoration (60-100) takes 50-100 years beyond most simulation runs.
   359→ *
   360→ * @param state - Current game state
   361→ * @returns Ecological score (0-100)
   362→ */
   363→function calculateEcological(state: GameState): number {
   364→  const MIN_FLOOR = 0.1;
   365→
   366→  // Planetary Boundaries: Use progressive recovery scoring (Oct 21, 2025)
   367→  // Replaces simple binary breach counting with impact-weighted recovery progress
   368→  const { calculateProgressiveEcologicalScore } = require('../../planetaryBoundaryRecovery');
   369→  const boundariesScore = calculateProgressiveEcologicalScore(state);
   370→
   371→  // Resource Reserves (0-1 → 0-100)
   372→  if (state.environmentalAccumulation?.resourceReserves === undefined) {
   373→    throw new Error('❌ state.environmentalAccumulation.resourceReserves is undefined in calculateEcological:320 - initialization bug');
   374→  }
   375→  const resourceReserves = state.environmentalAccumulation.resourceReserves;
   376→  const resourceScore = resourceReserves * 100;
   377→
   378→  // Climate Stability (0-1 → 0-100)
   379→  if (state.environmentalAccumulation?.climateStability === undefined) {
   380→    throw new Error('❌ state.environmentalAccumulation.climateStability is undefined in calculateEcological:324 - initialization bug');
   381→  }
   382→  const climateStability = state.environmentalAccumulation.climateStability;
   383→  const climateScore = climateStability * 100;
   384→
   385→  // Pollution (0-1 → 100-0, inverted)
   386→  if (state.environmentalAccumulation?.pollutionLevel === undefined) {
   387→    throw new Error('❌ state.environmentalAccumulation.pollutionLevel is undefined in calculateEcological:328 - initialization bug');
   388→  }
   389→  const pollutionLevel = state.environmentalAccumulation.pollutionLevel;
   390→  const pollutionScore = (1 - pollutionLevel) * 100;
   391→
   392→  // DEBUG: Log when any value is problematic
   393→  if (state.currentMonth % 12 === 0 || isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore)) {
   394→    const hasNaN = isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore);
   395→    if (hasNaN || state.currentMonth === 168) {
   396→      console.log(`\n🔍 ECOLOGY DEBUG (Month ${state.currentMonth}):`);
   397→      console.log(`   boundariesScore: ${boundariesScore} (${isNaN(boundariesScore) ? 'NaN!' : 'ok'})`);
   398→      console.log(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   399→      console.log(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   400→      console.log(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   401→    }
   402→  }
   403→
   404→  // Geometric mean
   405→  const indicators = [boundariesScore, resourceScore, climateScore, pollutionScore];
   406→
   407→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   408→  for (let i = 0; i < indicators.length; i++) {
   409→    if (isNaN(indicators[i])) {
   410→      console.error(`❌ NaN in Ecological indicator ${i} at month ${state.currentMonth}`);
   411→      console.error(`   boundariesScore: ${boundariesScore}`);
   412→      console.error(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   413→      console.error(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   414→      console.error(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   415→      throw new Error(`NaN in Ecological paradigm calculation - indicator ${i} is NaN`);
   416→    }
   417→  }
   418→
   419→  const product = indicators.reduce((acc, val) => {
   420→    const floored = Math.max(val, MIN_FLOOR);
   421→    return acc * (floored / 100);
   422→  }, 1);
   423→
   424→  const result = Math.pow(product, 1 / indicators.length) * 100;
   425→
   426→  // Final NaN check - if this triggers, the bug is in geometric mean calculation
   427→  if (isNaN(result)) {
   428→    console.error(`❌ NaN result in Ecological calculation at month ${state.currentMonth}`);
   429→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   430→    throw new Error(`Ecological geometric mean produced NaN - THIS IS THE BUG WE FIXED!`);
   431→  }
   432→
   433→  return result;
   434→}
