   436→/**
   437→ * Calculate Indigenous paradigm score from simulation state
   438→ *
   439→ * Indicators:
   440→ * - Social Trust (40%): state.socialCohesion.trust
   441→ * - Community Bonds (40%): state.socialCohesion.communityBonds
   442→ * - Meaning Crisis (20%): 100 - meaningCrisis (inverted)
   443→ *
   444→ * @param state - Current game state
   445→ * @returns Indigenous score (0-100)
   446→ */
   447→function calculateIndigenous(state: GameState): number {
   448→  const MIN_FLOOR = 0.1;
   449→
   450→  // Social Trust (0-100)
   451→  if (state.socialAccumulation?.socialCohesion?.trust === undefined) {
   452→    throw new Error('❌ state.socialAccumulation.socialCohesion.trust is undefined in calculateIndigenous:390 - initialization bug');
   453→  }
   454→  const socialTrust = state.socialAccumulation.socialCohesion.trust;
   455→
   456→  // Community Bonds (0-100)
   457→  if (state.socialAccumulation?.socialCohesion?.communityBonds === undefined) {
   458→    throw new Error('❌ state.socialAccumulation.socialCohesion.communityBonds is undefined in calculateIndigenous:393 - initialization bug');
   459→  }
   460→  const communityBonds = state.socialAccumulation.socialCohesion.communityBonds;
   461→
   462→  // Meaning Crisis (0-1, inverted to 0-100)
   463→  if (state.socialAccumulation?.meaningCrisisLevel === undefined) {
   464→    throw new Error('❌ state.socialAccumulation.meaningCrisisLevel is undefined in calculateIndigenous:396 - initialization bug');
   465→  }
   466→  const meaningCrisisLevel = state.socialAccumulation.meaningCrisisLevel;
   467→  const meaningScore = (1 - meaningCrisisLevel) * 100;
   468→
   469→  // Geometric mean
   470→  const indicators = [socialTrust, communityBonds, meaningScore];
