            boundary.currentValue - value * 0.01
          ), {
        location: 'applyRegionalEffects:biodiversityBonus',
        valueName: 'currentValue',
        month: gameState.currentMonth
      });
        }
        break;

      case 'habitatRestorationActive':
        // Flag that habitat restoration is deployed
