            console.log(`  ♻️ Plastic Pollution Reduction: novel_entities ${oldValue.toFixed(3)} → ${boundary.currentValue.toFixed(3)} (Δ=${(value * 0.01).toFixed(4)}) | Month ${gameState.currentMonth}`);
