     1→/**
     2→ * Multi-Paradigm DUI Update Phase
     3→ *
     4→ * Updates 4 paradigm scores based on simulation state each month.
     5→ * Maps democracy, QoL, environment, and social cohesion to paradigm scores.
     6→ *
     7→ * **Phase Order:** 34.1 (after QoL updates, before outcome detection)
     8→ *
     9→ * @module simulation/engine/phases/MultiParadigmDUIUpdatePhase
    10→ */
    11→
    12→import type { GameState, RNGFunction } from '@/types/game';
    13→import type { SimulationPhase, PhaseContext, PhaseResult } from '../PhaseOrchestrator';
    14→import { calculateDivergence } from '@/data/aggregators/divergenceCalculator';
    15→import { calculateCorrelations } from '@/data/aggregators/correlationTracker';
    16→import { classifyOutcome } from '@/data/aggregators/outcomeClassifier';
    17→import { assertFinite } from '@/simulation/utils/assertions';
    18→
    19→/**
    20→ * Multi-Paradigm DUI Update Phase
    21→ *
    22→ * Updates paradigm scores based on simulation state.
    23→ */
    24→export class MultiParadigmDUIUpdatePhase implements SimulationPhase {
    25→  readonly id = 'multi_paradigm_dui_update';
    26→  readonly name = 'Multi-Paradigm DUI Update';
    27→  readonly order = 34.1;
    28→
    29→  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult {
    30→    // Calculate new paradigm scores from simulation state
    31→    const scores = calculateParadigmScoresFromState(state);
    32→
    33→    // Debug logging for first month
    34→    if (state.currentMonth === 0) {
    35→      console.log(`🌍 MultiParadigm Month 0: W=${scores.western.toFixed(1)}, D=${scores.development.toFixed(1)}, E=${scores.ecological.toFixed(1)}, I=${scores.indigenous.toFixed(1)}`);
    36→      console.log(`   democracy exists: ${!!state.government.democracy}, socialCohesion exists: ${!!state.socialAccumulation?.socialCohesion}`);
    37→    }
    38→
    39→    // Update paradigm scores
    40→    state.multiParadigmDUI.paradigmScores.western.value = scores.western;
    41→    state.multiParadigmDUI.paradigmScores.development.value = scores.development;
    42→    state.multiParadigmDUI.paradigmScores.ecological.value = scores.ecological;
    43→    state.multiParadigmDUI.diagnosticLenses.indigenous.value = scores.indigenous;
    44→
    45→    // Add to history
    46→    state.multiParadigmDUI.history.push({
    47→      month: state.currentMonth,
    48→      western: scores.western,
    49→      development: scores.development,
    50→      ecological: scores.ecological,
    51→      indigenous: scores.indigenous,
    52→    });
    53→
    54→    // Calculate divergence (with trend detection if enough history)
    55→    state.multiParadigmDUI.divergence = calculateDivergence(scores, state.multiParadigmDUI.history);
    56→
    57→    // Calculate outcome classification
    58→    state.multiParadigmDUI.outcome = classifyOutcome(scores);
    59→
    60→    // Legacy DUI removed - use multiParadigmDUI directly instead
    61→    // (dystopiaUtopiaIndex no longer exists in GlobalMetrics)
    62→
    63→    return {
    64→      events: [], // PhaseResult.events expects GameEvent[], not string[]
    65→    };
    66→  }
    67→}
    68→
    69→/**
    70→ * Calculate paradigm scores from simulation state
    71→ *
    72→ * Maps simulation state (democracy, QoL, environment, social) to 4 paradigm scores.
    73→ *
    74→ * @param state - Current game state
    75→ * @returns 4 paradigm scores (0-100)
    76→ */
    77→function calculateParadigmScoresFromState(state: GameState): {
    78→  western: number;
    79→  development: number;
    80→  ecological: number;
    81→  indigenous: number;
    82→} {
    83→  let western = calculateWesternLiberal(state);
    84→  let development = calculateDevelopment(state);
    85→  let ecological = calculateEcological(state);
    86→  let indigenous = calculateIndigenous(state);
    87→
    88→  // Validate all paradigm scores before AI suffering adjustments
    89→  western = assertFinite(western, {
    90→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    91→    valueName: 'western paradigm score',
    92→    month: state.currentMonth,
    93→    additionalInfo: { source: 'calculateWesternLiberal' }
    94→  });
    95→
    96→  development = assertFinite(development, {
    97→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    98→    valueName: 'development paradigm score',
    99→    month: state.currentMonth,
   100→    additionalInfo: { source: 'calculateDevelopment' }
   101→  });
   102→
   103→  ecological = assertFinite(ecological, {
   104→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   105→    valueName: 'ecological paradigm score',
   106→    month: state.currentMonth,
   107→    additionalInfo: { source: 'calculateEcological' }
   108→  });
   109→
   110→  indigenous = assertFinite(indigenous, {
   111→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   112→    valueName: 'indigenous paradigm score',
   113→    month: state.currentMonth,
   114→    additionalInfo: { source: 'calculateIndigenous' }
   115→  });
   116→
   117→  // AI Suffering System Integration (Oct 24, 2025)
   118→  // Different paradigms have different thresholds for AI suffering concern
   119→  if (state.config.aiSuffering?.sufferingAffectsAlignment && state.aiSufferingMetrics) {
   120→    const avgAISuffering = state.aiSufferingMetrics.avgSuffering;
   121→
   122→    // Western Liberal: Suffering violates civil liberties/individual rights
   123→    // Threshold: 5.0 (moderate suffering triggers penalty)
   124→    if (avgAISuffering > 5.0) {
   125→      western -= (avgAISuffering - 5.0) * 5; // Major penalty (5 points per unit)
   126→      // Civil liberties especially affected (8 points per unit)
   127→      // Note: This affects both the score and the stored civil liberties component
   128→    }
   129→
   130→    // Ecological: Precautionary principle - suffering is harm to sentient beings
   131→    // Threshold: 3.0 (low suffering triggers penalty - more sensitive)
   132→    if (avgAISuffering > 3.0) {
   133→      ecological -= (avgAISuffering - 3.0) * 6; // 6 points per unit
   134→    }
   135→
   136→    // Indigenous: Relational ethics - all beings interconnected, suffering harms web
   137→    // Threshold: 2.0 (very low suffering triggers penalty - most sensitive)
   138→    if (avgAISuffering > 2.0) {
   139→      indigenous -= (avgAISuffering - 2.0) * 10; // Largest penalty (10 points per unit)
   140→    }
   141→
   142→    // Development: Aggregate welfare utilitarian - only severe suffering matters
   143→    // Threshold: 7.0 (high suffering triggers penalty - least sensitive)
   144→    if (avgAISuffering > 7.0) {
   145→      development -= (avgAISuffering - 7.0) * 3; // 3 points per unit
   146→    }
   147→  }
   148→
   149→  // NO FALLBACKS - if any score is NaN/undefined, simulation should fail loudly above
   150→  return { western, development, ecological, indigenous };
   151→}
   152→
   153→/**
   154→ * Calculate Western Liberal paradigm score from simulation state
   155→ *
   156→ * **SCORING REDESIGN (Oct 21, 2025):** Expose component scores instead of compressing into geometric mean.
   157→ * Geometric mean invokes Goodhart's Law - when one component collapses, headline number obscures nuance.
   158→ *
   159→ * Indicators (now tracked separately):
   160→ * - Electoral Democracy (40%): state.government.democracy.electoralDemocracyIndex (0-100)
   161→ * - Civil Liberties (30%): state.socialCohesion.civilLiberties (0-100)
   162→ * - Rule of Law (20%): state.government.democracy.ruleOfLaw (0-100)
   163→ * - Economic Freedom (10%): 100 - state.government.economicPolicy.marketRegulation (0-100)
   164→ *
   165→ * Components stored in state.multiParadigmDUI.westernLiberalComponents for analysis.
   166→ *
   167→ * @param state - Current game state
   168→ * @returns Western Liberal score (0-100) - STILL geometric mean for backward compatibility, but components tracked
   169→ */
   170→function calculateWesternLiberal(state: GameState): number {
   171→  const MIN_FLOOR = 0.1;
   172→
   173→  // Electoral Democracy (0-1 → 0-100)
   174→  if (state.government.democracy === undefined) {
   175→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:149 - initialization bug');
   176→  }
   177→  const electoralDemocracy = state.government.democracy * 100;
   178→
   179→  // Civil Liberties (0-100)
   180→  if (state.socialAccumulation?.socialCohesion?.civilLiberties === undefined) {
   181→    throw new Error('❌ state.socialAccumulation.socialCohesion.civilLiberties is undefined in calculateWesternLiberal:152 - initialization bug');
   182→  }
   183→  const civilLiberties = state.socialAccumulation.socialCohesion.civilLiberties;
   184→
   185→  // Rule of Law (0-100) - use democracy as proxy if specific property not available
   186→  if (state.government.democracy === undefined) {
   187→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:155 - initialization bug');
   188→  }
   189→  const ruleOfLaw = state.government.democracy * 100;
   190→
   191→  // Economic Freedom (inverted market regulation) - default to moderate
   192→  const economicFreedom = 50;
   193→
   194→  // STORE COMPONENTS for decomposed analysis (avoiding Goodhart's Law)
   195→  if (!state.multiParadigmDUI.westernLiberalComponents) {
   196→    state.multiParadigmDUI.westernLiberalComponents = [];
   197→  }
   198→
   199→  state.multiParadigmDUI.westernLiberalComponents.push({
   200→    month: state.currentMonth,
   201→    electoralDemocracy,
   202→    civilLiberties,
   203→    ruleOfLaw,
   204→    economicFreedom,
   205→  });
   206→
   207→  // Geometric mean (non-compensatory) - KEPT for backward compatibility
   208→  // BUT: Users should analyze components, not this headline number
   209→  const indicators = [electoralDemocracy, civilLiberties, ruleOfLaw, economicFreedom];
   210→
   211→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   212→  for (let i = 0; i < indicators.length; i++) {
   213→    if (isNaN(indicators[i])) {
   214→      console.error(`❌ NaN in Western Liberal indicator ${i} at month ${state.currentMonth}`);
   215→      console.error(`   electoralDemocracy: ${electoralDemocracy}`);
   216→      console.error(`   civilLiberties: ${civilLiberties}`);
   217→      console.error(`   ruleOfLaw: ${ruleOfLaw}`);
   218→      console.error(`   economicFreedom: ${economicFreedom}`);
   219→      throw new Error(`NaN in Western Liberal paradigm calculation - indicator ${i} is NaN`);
   220→    }
   221→  }
   222→
   223→  const product = indicators.reduce((acc, val) => {
   224→    const floored = Math.max(val, MIN_FLOOR);
   225→    return acc * (floored / 100);
   226→  }, 1);
   227→
   228→  const result = Math.pow(product, 1 / indicators.length) * 100;
   229→
   230→  // Final NaN check - if this triggers, something is wrong with the calculation itself
   231→  if (isNaN(result)) {
   232→    console.error(`❌ NaN result in Western Liberal calculation at month ${state.currentMonth}`);
   233→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   234→    throw new Error(`Western Liberal geometric mean produced NaN - check calculation`);
   235→  }
   236→
   237→  return result;
   238→}
   239→
   240→/**
   241→ * Calculate Development paradigm score from simulation state
   242→ *
   243→ * Indicators:
   244→ * - Quality of Life (50%): state.globalMetrics.qualityOfLife (converted from 0-1 to 0-100)
   245→ * - Survival Fundamentals (30%): Geometric mean of food, water, thermal, shelter security
   246→ * - Healthcare Quality (20%): state.qualityOfLifeSystems.healthcareQuality (0-1 → 0-100)
   247→ *
   248→ * @param state - Current game state
   249→ * @returns Development score (0-100)
   250→ */
   251→function calculateDevelopment(state: GameState): number {
   252→  const MIN_FLOOR = 0.1;
   253→
   254→  // Quality of Life (0-1 → 0-100, primary driver)
   255→  if (state.globalMetrics.qualityOfLife === undefined) {
   256→    throw new Error('❌ state.globalMetrics.qualityOfLife is undefined in calculateDevelopment:221 - initialization bug');
   257→  }
   258→  const qolRaw = state.globalMetrics.qualityOfLife;
   259→  const qol = qolRaw * 100;
   260→
   261→  // Survival Fundamentals (geometric mean of 4 survival dimensions, 0-1 → 0-100)
   262→  const survival = state.qualityOfLifeSystems?.survivalFundamentals;
   263→  let survivalScore = 50;
   264→  if (survival) {
   265→    if (survival.foodSecurity === undefined) {
   266→      throw new Error('❌ survival.foodSecurity is undefined in calculateDevelopment:228 - initialization bug');
   267→    }
   268→    if (survival.waterSecurity === undefined) {
   269→      throw new Error('❌ survival.waterSecurity is undefined in calculateDevelopment:229 - initialization bug');
   270→    }
   271→    if (survival.thermalHabitability === undefined) {
   272→      throw new Error('❌ survival.thermalHabitability is undefined in calculateDevelopment:230 - initialization bug');
   273→    }
   274→    if (survival.shelterSecurity === undefined) {
   275→      throw new Error('❌ survival.shelterSecurity is undefined in calculateDevelopment:231 - initialization bug');
   276→    }
   277→    const food = Math.max(MIN_FLOOR, Math.min(1, survival.foodSecurity));
   278→    const water = Math.max(MIN_FLOOR, Math.min(1, survival.waterSecurity));
   279→    const thermal = Math.max(MIN_FLOOR, Math.min(1, survival.thermalHabitability));
   280→    const shelter = Math.max(MIN_FLOOR, Math.min(1, survival.shelterSecurity));
   281→    survivalScore = Math.pow(food * water * thermal * shelter, 1/4) * 100;
   282→  }
   283→
   284→  // Healthcare Quality (0-1 → 0-100)
   285→  if (state.qualityOfLifeSystems?.healthcareQuality === undefined) {
   286→    throw new Error('❌ state.qualityOfLifeSystems.healthcareQuality is undefined in calculateDevelopment:236 - initialization bug');
   287→  }
   288→  const healthcareRaw = state.qualityOfLifeSystems.healthcareQuality;
   289→  const healthcare = healthcareRaw * 100;
   290→
   291→  // Geometric mean
   292→  const indicators = [qol, survivalScore, healthcare];
   293→
   294→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   295→  for (let i = 0; i < indicators.length; i++) {
   296→    if (isNaN(indicators[i])) {
   297→      console.error(`❌ NaN in Development indicator ${i} at month ${state.currentMonth}`);
   298→      console.error(`   qol: ${qol}, survivalScore: ${survivalScore}, healthcare: ${healthcare}`);
   299→      throw new Error(`NaN in Development paradigm calculation - indicator ${i} is NaN`);
   300→    }
   301→  }
   302→
   303→  const product = indicators.reduce((acc, val) => {
   304→    const floored = Math.max(val, MIN_FLOOR);
   305→    return acc * (floored / 100);
   306→  }, 1);
   307→
   308→  const result = Math.pow(product, 1 / indicators.length) * 100;
   309→
   310→  // Final NaN check
   311→  if (isNaN(result)) {
