  // QoL Tier Averages (for drill-down sparklines)
  qolTier0Avg: number[];
  qolTier1Avg: number[];
  qolTier2Avg: number[];
  qolTier3Avg: number[];
  qolTier4Avg: number[];
  qolTier5Avg: number[];
  qolGini: number[];
}

let metricHistory: MetricHistory = {
  westernLiberalIndex: [],
  developmentIndex: [],
  ecologicalIndex: [],
  indigenousIndex: [],
  qualityOfLife: [],
  population: [],
  climateChange: [],
  biodiversityLoss: [],
  socialCohesion: [],
  institutionalTrust: [],
  meaningLevel: [],
  governmentComprehension: [],
  internationalCooperation: [],
  governmentAIRegulation: [],
  qolTier0Avg: [],
  qolTier1Avg: [],
  qolTier2Avg: [],
  qolTier3Avg: [],
  qolTier4Avg: [],
  qolTier5Avg: [],
  qolGini: [],
};

// Previous state snapshot for delta calculation (expanded)
interface StateSnapshot {
  currentMonth: number;
  currentYear: number;
  qualityOfLife: number;
