     1→/**
     2→ * Quality of Life Dimension Calculations
     3→ *
     4→ * Calculates 17 QoL dimensions across 5 tiers:
     5→ * - Tier 0: Survival fundamentals (food, water, shelter, habitability)
     6→ * - Tier 1: Basic needs (material, energy, safety)
     7→ * - Tier 2: Psychological (mental health, meaning, connection, autonomy)
     8→ * - Tier 3: Social (freedom, information, community, culture)
     9→ * - Tier 4: Health (healthcare, longevity, disease burden)
    10→ * - Tier 5: Environmental (ecosystem, climate, pollution)
    11→ *
    12→ * Research basis: Multi-dimensional wellbeing frameworks (Sen, Nussbaum)
    13→ * Each dimension has research-backed thresholds and relationships.
    14→ */
    15→
    16→import type { GameState, QualityOfLifeSystems } from '@/types/game';
    17→import { getTrustInAI } from '../socialCohesion';
    18→import { getTechDeploymentSafe } from '../techTree/helpers';
    19→import { assertProbability } from '../utils/assertions';
    20→
    21→/**
    22→ * Calculate Tier 0: Survival Fundamentals (NON-FOOD ONLY)
    23→ *
    24→ * FIX (Oct 25, 2025): Food security is now REGIONAL and aggregated separately
    25→ * This function calculates ONLY water, thermal, and shelter security
    26→ *
    27→ * These CANNOT be averaged away - track minimums, not means.
    28→ * Required for Utopia determination.
    29→ */
    30→export function calculateNonFoodSurvivalMetrics(state: GameState): { waterSecurity: number; thermalHabitability: number; shelterSecurity: number } {
    31→  const rawWaterSecurity = calculateWaterSecurity(state);
    32→  const rawThermalHabitability = calculateThermalHabitability(state);
    33→  const rawShelterSecurity = calculateShelterSecurity(state);
    34→
    35→  // FIX (Oct 25, 2025): Replaced defensive NaN guards with assertive validation
    36→  // If any calculation produces NaN, that's a BUG that needs fixing, not a value to replace
    37→  const month = state.currentMonth;
    38→  const location = 'calculateNonFoodSurvivalMetrics';
    39→
    40→  return {
    41→    waterSecurity: assertProbability(rawWaterSecurity, { location, valueName: 'waterSecurity', month }),
    42→    thermalHabitability: assertProbability(rawThermalHabitability, { location, valueName: 'thermalHabitability', month }),
    43→    shelterSecurity: assertProbability(rawShelterSecurity, { location, valueName: 'shelterSecurity', month }),
    44→  };
    45→}
    46→
    47→/**
    48→ * REMOVED (Oct 25, 2025): calculateFoodSecurity() function
    49→ *
    50→ * Food security is now fully REGIONAL with no global recalculation.
    51→ *
    52→ * Regional food security is PERSISTENT STATE:
    53→ * - Initialized to realistic regional values (65-95% by region)
    54→ * - Modified by FoodSecurityDegradationPhase (crisis degradation, vulnerability-weighted)
    55→ * - Modified by tech deployment (vertical farming, etc.)
    56→ * - Global food security = population-weighted average of regional values
    57→ *
    58→ * This architecture preserves regional variation and prevents all regions
    59→ * from converging to the same global baseline.
    60→ */
    61→
    62→/**
    63→ * Calculate water security across population
    64→ *
    65→ * Research basis:
    66→ * - WHO: 50L/day minimum for health (drinking, cooking, hygiene)
    67→ * - 20L/day survival minimum
    68→ * - Freshwater depletion, climate change, pollution all threaten water access
    69→ */
    70→export function calculateWaterSecurity(state: GameState): number {
    71→  const resources = state.resourceEconomy;
    72→  const freshwater = state.freshwaterSystem;
    73→
    74→  // Base water availability from resource stocks
    75→  let waterSecurity = Math.min(1.0, resources.water.reserves);
    76→
    77→  // === FRESHWATER DEPLETION ===
    78→  // Day Zero droughts = acute water crisis
    79→  if (freshwater && freshwater.dayZeroDrought.active) {
    80→    const droughtSeverity = freshwater.dayZeroDrought.severity;
    81→    waterSecurity -= droughtSeverity * 0.4; // Up to 40% reduction
    82→  }
    83→
    84→  // Peak Groundwater = declining availability
    85→  if (freshwater && freshwater.peakGroundwaterReached) {
    86→    const depletionRate = freshwater.blueWater.depletionRate;
    87→    waterSecurity -= depletionRate * 0.3;
    88→  }
    89→
    90→  // General water stress
    91→  if (freshwater && freshwater.waterStress > 0.40) {
    92→    const stressPenalty = (freshwater.waterStress - 0.40) * 0.5;
    93→    waterSecurity -= stressPenalty;
    94→  }
    95→
    96→  // === CLIMATE IMPACT ===
    97→  // Temperature anomalies disrupt water cycle
    98→  // Research: Each 1°C = 7% more atmospheric water vapor = more droughts AND floods
    99→  const tempAnomaly = resources.co2.temperatureAnomaly;
   100→  if (tempAnomaly > 2.0) {
   101→    const climatePenalty = (tempAnomaly - 2.0) * 0.1;
   102→    waterSecurity -= climatePenalty;
   103→  }
   104→
   105→  // === POLLUTION ===
   106→  // Novel entities (PFAS, microplastics) contaminate water supplies
   107→  if (state.novelEntitiesSystem && state.novelEntitiesSystem.pfasPrevalence > 0.70) {
   108→    const contamination = (state.novelEntitiesSystem.pfasPrevalence - 0.70) / 0.30; // 0.70-1.0 scale
   109→    waterSecurity -= contamination * 0.15; // Up to 15% reduction
   110→  }
   111→
   112→  // === AI ENHANCEMENT ===
   113→  // Desalination, water purification, infrastructure optimization
   114→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   115→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
   116→  if (totalAI > 1.5 && avgAlignment > 0.7) {
   117→    const aiWater = Math.min(0.25, (totalAI - 1.5) * 0.08);
   118→    waterSecurity += aiWater;
   119→  }
   120→
   121→  // === BREAKTHROUGH TECHNOLOGY ===
   122→  // Clean energy enables desalination at scale
   123→  const cleanEnergy = getTechDeploymentSafe(state, 'cleanEnergy');
   124→  waterSecurity += cleanEnergy * 0.15; // Desalination powered by clean energy
   125→
   126→  // FIX (Oct 25, 2025): Cap at 1.0, not 1.5 - waterSecurity is a probability [0, 1]
   127→  // Bug found by assertProbability: waterSecurity was reaching 1.096
   128→  return Math.max(0, Math.min(1.0, waterSecurity));
   129→}
   130→
   131→/**
   132→ * Calculate thermal habitability of planet
   133→ *
   134→ * Research basis:
   135→ * - Sherwood & Huber (2010): Wet-bulb 35°C = death in ~6 hours
   136→ * - IPCC: +2°C makes Middle East, Pakistan, India marginal
   137→ * - +4°C: Tropical belt dangerous for outdoor work
   138→ */
   139→export function calculateThermalHabitability(state: GameState): number {
   140→  const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
   141→
   142→  // Base habitability by temperature anomaly
   143→  let habitableFraction = 1.0;
   144→
   145→  if (tempAnomaly < 1.5) {
