     1→/**
     2→ * Multi-Paradigm DUI Update Phase
     3→ *
     4→ * Updates 4 paradigm scores based on simulation state each month.
     5→ * Maps democracy, QoL, environment, and social cohesion to paradigm scores.
     6→ *
     7→ * **Phase Order:** 34.1 (after QoL updates, before outcome detection)
     8→ *
     9→ * @module simulation/engine/phases/MultiParadigmDUIUpdatePhase
    10→ */
    11→
    12→import type { GameState, RNGFunction } from '@/types/game';
    13→import type { SimulationPhase, PhaseContext, PhaseResult } from '../PhaseOrchestrator';
    14→import { calculateDivergence } from '@/data/aggregators/divergenceCalculator';
    15→import { calculateCorrelations } from '@/data/aggregators/correlationTracker';
    16→import { classifyOutcome } from '@/data/aggregators/outcomeClassifier';
    17→import { assertFinite } from '@/simulation/utils/assertions';
    18→
    19→/**
    20→ * Multi-Paradigm DUI Update Phase
    21→ *
    22→ * Updates paradigm scores based on simulation state.
    23→ */
    24→export class MultiParadigmDUIUpdatePhase implements SimulationPhase {
    25→  readonly id = 'multi_paradigm_dui_update';
    26→  readonly name = 'Multi-Paradigm DUI Update';
    27→  readonly order = 34.1;
    28→
    29→  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult {
    30→    // Calculate new paradigm scores from simulation state
    31→    const scores = calculateParadigmScoresFromState(state);
    32→
    33→    // Debug logging for first month
    34→    if (state.currentMonth === 0) {
    35→      console.log(`🌍 MultiParadigm Month 0: W=${scores.western.toFixed(1)}, D=${scores.development.toFixed(1)}, E=${scores.ecological.toFixed(1)}, I=${scores.indigenous.toFixed(1)}`);
    36→      console.log(`   democracy exists: ${!!state.government.democracy}, socialCohesion exists: ${!!state.socialAccumulation?.socialCohesion}`);
    37→    }
    38→
    39→    // Update paradigm scores
    40→    state.multiParadigmDUI.paradigmScores.western.value = scores.western;
    41→    state.multiParadigmDUI.paradigmScores.development.value = scores.development;
    42→    state.multiParadigmDUI.paradigmScores.ecological.value = scores.ecological;
    43→    state.multiParadigmDUI.diagnosticLenses.indigenous.value = scores.indigenous;
    44→
    45→    // Add to history
    46→    state.multiParadigmDUI.history.push({
    47→      month: state.currentMonth,
    48→      western: scores.western,
    49→      development: scores.development,
    50→      ecological: scores.ecological,
    51→      indigenous: scores.indigenous,
    52→    });
    53→
    54→    // Calculate divergence (with trend detection if enough history)
    55→    state.multiParadigmDUI.divergence = calculateDivergence(scores, state.multiParadigmDUI.history);
    56→
    57→    // Calculate outcome classification
    58→    state.multiParadigmDUI.outcome = classifyOutcome(scores);
    59→
    60→    // Legacy DUI removed - use multiParadigmDUI directly instead
    61→    // (dystopiaUtopiaIndex no longer exists in GlobalMetrics)
    62→
    63→    return {
    64→      events: [], // PhaseResult.events expects GameEvent[], not string[]
    65→    };
    66→  }
    67→}
    68→
    69→/**
    70→ * Calculate paradigm scores from simulation state
    71→ *
    72→ * Maps simulation state (democracy, QoL, environment, social) to 4 paradigm scores.
    73→ *
    74→ * @param state - Current game state
    75→ * @returns 4 paradigm scores (0-100)
    76→ */
    77→function calculateParadigmScoresFromState(state: GameState): {
    78→  western: number;
    79→  development: number;
    80→  ecological: number;
    81→  indigenous: number;
    82→} {
    83→  let western = calculateWesternLiberal(state);
    84→  let development = calculateDevelopment(state);
    85→  let ecological = calculateEcological(state);
    86→  let indigenous = calculateIndigenous(state);
    87→
    88→  // Validate all paradigm scores before AI suffering adjustments
    89→  western = assertFinite(western, {
    90→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    91→    valueName: 'western paradigm score',
    92→    month: state.currentMonth,
    93→    additionalInfo: { source: 'calculateWesternLiberal' }
    94→  });
    95→
    96→  development = assertFinite(development, {
    97→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
    98→    valueName: 'development paradigm score',
    99→    month: state.currentMonth,
   100→    additionalInfo: { source: 'calculateDevelopment' }
   101→  });
   102→
   103→  ecological = assertFinite(ecological, {
   104→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   105→    valueName: 'ecological paradigm score',
   106→    month: state.currentMonth,
   107→    additionalInfo: { source: 'calculateEcological' }
   108→  });
   109→
   110→  indigenous = assertFinite(indigenous, {
   111→    location: 'MultiParadigmDUIUpdatePhase.calculateParadigmScoresFromState',
   112→    valueName: 'indigenous paradigm score',
   113→    month: state.currentMonth,
   114→    additionalInfo: { source: 'calculateIndigenous' }
   115→  });
   116→
   117→  // AI Suffering System Integration (Oct 24, 2025)
   118→  // Different paradigms have different thresholds for AI suffering concern
   119→  if (state.config.aiSuffering?.sufferingAffectsAlignment && state.aiSufferingMetrics) {
   120→    const avgAISuffering = state.aiSufferingMetrics.avgSuffering;
   121→
   122→    // Western Liberal: Suffering violates civil liberties/individual rights
   123→    // Threshold: 5.0 (moderate suffering triggers penalty)
   124→    if (avgAISuffering > 5.0) {
   125→      western -= (avgAISuffering - 5.0) * 5; // Major penalty (5 points per unit)
   126→      // Civil liberties especially affected (8 points per unit)
   127→      // Note: This affects both the score and the stored civil liberties component
   128→    }
   129→
   130→    // Ecological: Precautionary principle - suffering is harm to sentient beings
   131→    // Threshold: 3.0 (low suffering triggers penalty - more sensitive)
   132→    if (avgAISuffering > 3.0) {
   133→      ecological -= (avgAISuffering - 3.0) * 6; // 6 points per unit
   134→    }
   135→
   136→    // Indigenous: Relational ethics - all beings interconnected, suffering harms web
   137→    // Threshold: 2.0 (very low suffering triggers penalty - most sensitive)
   138→    if (avgAISuffering > 2.0) {
   139→      indigenous -= (avgAISuffering - 2.0) * 10; // Largest penalty (10 points per unit)
   140→    }
   141→
   142→    // Development: Aggregate welfare utilitarian - only severe suffering matters
   143→    // Threshold: 7.0 (high suffering triggers penalty - least sensitive)
   144→    if (avgAISuffering > 7.0) {
   145→      development -= (avgAISuffering - 7.0) * 3; // 3 points per unit
   146→    }
   147→  }
   148→
   149→  // NO FALLBACKS - if any score is NaN/undefined, simulation should fail loudly above
   150→  return { western, development, ecological, indigenous };
   151→}
   152→
   153→/**
   154→ * Calculate Western Liberal paradigm score from simulation state
   155→ *
   156→ * **SCORING REDESIGN (Oct 21, 2025):** Expose component scores instead of compressing into geometric mean.
   157→ * Geometric mean invokes Goodhart's Law - when one component collapses, headline number obscures nuance.
   158→ *
   159→ * **SURVEILLANCE ADDITION (Oct 27, 2025):** Added privacy/freedom from surveillance as 5th component.
   160→ *
   161→ * Indicators (now tracked separately):
   162→ * - Electoral Democracy (20%): state.government.democracy (0-100)
   163→ * - Civil Liberties (20%): state.socialCohesion.civilLiberties (0-100)
   164→ * - Rule of Law (20%): state.government.democracy as proxy (0-100)
   165→ * - Economic Freedom (20%): Default 50 (placeholder, will be implemented)
   166→ * - Privacy/Freedom from Surveillance (20%): (1 - surveillanceLevel) * 100 (0-100)
   167→ *
   168→ * Components stored in state.multiParadigmDUI.westernLiberalComponents for analysis.
   169→ *
   170→ * @param state - Current game state
   171→ * @returns Western Liberal score (0-100) - STILL geometric mean for backward compatibility, but components tracked
   172→ */
   173→function calculateWesternLiberal(state: GameState): number {
   174→  const MIN_FLOOR = 0.1;
   175→
   176→  // Electoral Democracy (0-1 → 0-100)
   177→  if (state.government.democracy === undefined) {
   178→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:149 - initialization bug');
   179→  }
   180→  const electoralDemocracy = state.government.democracy * 100;
   181→
   182→  // Civil Liberties (0-100)
   183→  if (state.socialAccumulation?.socialCohesion?.civilLiberties === undefined) {
   184→    throw new Error('❌ state.socialAccumulation.socialCohesion.civilLiberties is undefined in calculateWesternLiberal:152 - initialization bug');
   185→  }
   186→  const civilLiberties = state.socialAccumulation.socialCohesion.civilLiberties;
   187→
   188→  // Rule of Law (0-100) - use institutionalLegitimacy (independent judiciary, property rights, equal treatment)
   189→  // FIX (Oct 27, 2025): Was duplicate of democracy - now uses distinct metric
   190→  if (state.socialAccumulation?.institutionalLegitimacy === undefined) {
   191→    throw new Error('❌ state.socialAccumulation.institutionalLegitimacy is undefined in calculateWesternLiberal:155 - initialization bug');
   192→  }
   193→  const ruleOfLaw = state.socialAccumulation.institutionalLegitimacy * 100;
   194→
   195→  // Economic Freedom (0-100) - map from AI regulation level (inverted)
   196→  // FIX (Oct 27, 2025): Was hardcoded to 50 - now uses actual regulation type
   197→  // Western Liberal paradigm values free markets, so less regulation = higher score
   198→  const regulationType = state.government.structuralChoices.regulationType;
   199→  let economicFreedom: number;
   200→  switch (regulationType) {
   201→    case 'none':
   202→      economicFreedom = 100; // Laissez-faire, no AI regulation
   203→      break;
   204→    case 'large_companies':
   205→      economicFreedom = 75; // Light regulation (only big players)
   206→      break;
   207→    case 'compute_threshold':
   208→      economicFreedom = 50; // Moderate regulation (compute-based)
   209→      break;
   210→    case 'capability_ceiling':
   211→      economicFreedom = 25; // Heavy regulation (capability limits)
   212→      break;
   213→    default:
   214→      economicFreedom = 100; // Default to no regulation
   215→  }
   216→
   217→  // Privacy/Freedom from Surveillance (0-100) - invert surveillance level
   218→  const surveillanceLevel = state.government.structuralChoices.surveillanceLevel;
   219→  const privacyFreedom = (1 - surveillanceLevel) * 100;
   220→
   221→  // STORE COMPONENTS for decomposed analysis (avoiding Goodhart's Law)
   222→  if (!state.multiParadigmDUI.westernLiberalComponents) {
   223→    state.multiParadigmDUI.westernLiberalComponents = [];
   224→  }
   225→
   226→  state.multiParadigmDUI.westernLiberalComponents.push({
   227→    month: state.currentMonth,
   228→    electoralDemocracy,
   229→    civilLiberties,
   230→    ruleOfLaw,
   231→    economicFreedom,
   232→    privacyFreedom,
   233→  });
   234→
   235→  // Geometric mean (non-compensatory) - KEPT for backward compatibility
   236→  // BUT: Users should analyze components, not this headline number
   237→  const indicators = [electoralDemocracy, civilLiberties, ruleOfLaw, economicFreedom, privacyFreedom];
   238→
   239→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   240→  for (let i = 0; i < indicators.length; i++) {
   241→    if (isNaN(indicators[i])) {
   242→      console.error(`❌ NaN in Western Liberal indicator ${i} at month ${state.currentMonth}`);
   243→      console.error(`   electoralDemocracy: ${electoralDemocracy}`);
   244→      console.error(`   civilLiberties: ${civilLiberties}`);
   245→      console.error(`   ruleOfLaw: ${ruleOfLaw}`);
   246→      console.error(`   economicFreedom: ${economicFreedom}`);
   247→      console.error(`   privacyFreedom: ${privacyFreedom}`);
   248→      throw new Error(`NaN in Western Liberal paradigm calculation - indicator ${i} is NaN`);
   249→    }
   250→  }
   251→
   252→  const product = indicators.reduce((acc, val) => {
   253→    const floored = Math.max(val, MIN_FLOOR);
   254→    return acc * (floored / 100);
   255→  }, 1);
   256→
   257→  const result = Math.pow(product, 1 / indicators.length) * 100;
   258→
   259→  // Final NaN check - if this triggers, something is wrong with the calculation itself
   260→  if (isNaN(result)) {
   261→    console.error(`❌ NaN result in Western Liberal calculation at month ${state.currentMonth}`);
   262→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   263→    throw new Error(`Western Liberal geometric mean produced NaN - check calculation`);
   264→  }
   265→
   266→  return result;
   267→}
   268→
   269→/**
   270→ * Calculate Development paradigm score from simulation state
   271→ *
   272→ * Indicators:
   273→ * - Quality of Life (50%): state.globalMetrics.qualityOfLife (converted from 0-1 to 0-100)
   274→ * - Survival Fundamentals (30%): Geometric mean of food, water, thermal, shelter security
   275→ * - Healthcare Quality (20%): state.qualityOfLifeSystems.healthcareQuality (0-1 → 0-100)
   276→ *
   277→ * @param state - Current game state
   278→ * @returns Development score (0-100)
   279→ */
   280→function calculateDevelopment(state: GameState): number {
   281→  const MIN_FLOOR = 0.1;
   282→
   283→  // Quality of Life (0-1 → 0-100, primary driver)
   284→  if (state.globalMetrics.qualityOfLife === undefined) {
   285→    throw new Error('❌ state.globalMetrics.qualityOfLife is undefined in calculateDevelopment:221 - initialization bug');
   286→  }
   287→  const qolRaw = state.globalMetrics.qualityOfLife;
   288→  const qol = qolRaw * 100;
   289→
   290→  // Survival Fundamentals (geometric mean of 4 survival dimensions, 0-1 → 0-100)
   291→  // FIX (Oct 27, 2025): Removed silent fallback to 50 - fail loudly if survival undefined
   292→  const survival = state.qualityOfLifeSystems?.survivalFundamentals;
   293→  if (!survival) {
   294→    throw new Error('❌ state.qualityOfLifeSystems.survivalFundamentals is undefined in calculateDevelopment:228 - initialization bug');
   295→  }
   296→  if (survival.foodSecurity === undefined) {
   297→    throw new Error('❌ survival.foodSecurity is undefined in calculateDevelopment:229 - initialization bug');
   298→  }
   299→  if (survival.waterSecurity === undefined) {
   300→    throw new Error('❌ survival.waterSecurity is undefined in calculateDevelopment:230 - initialization bug');
   301→  }
   302→  if (survival.thermalHabitability === undefined) {
   303→    throw new Error('❌ survival.thermalHabitability is undefined in calculateDevelopment:231 - initialization bug');
   304→  }
   305→  if (survival.shelterSecurity === undefined) {
   306→    throw new Error('❌ survival.shelterSecurity is undefined in calculateDevelopment:232 - initialization bug');
   307→  }
   308→  const food = Math.max(MIN_FLOOR, Math.min(1, survival.foodSecurity));
   309→  const water = Math.max(MIN_FLOOR, Math.min(1, survival.waterSecurity));
   310→  const thermal = Math.max(MIN_FLOOR, Math.min(1, survival.thermalHabitability));
   311→  const shelter = Math.max(MIN_FLOOR, Math.min(1, survival.shelterSecurity));
   312→  const survivalScore = Math.pow(food * water * thermal * shelter, 1/4) * 100;
   313→
   314→  // Healthcare Quality (0-1 → 0-100)
   315→  if (state.qualityOfLifeSystems?.healthcareQuality === undefined) {
   316→    throw new Error('❌ state.qualityOfLifeSystems.healthcareQuality is undefined in calculateDevelopment:236 - initialization bug');
   317→  }
   318→  const healthcareRaw = state.qualityOfLifeSystems.healthcareQuality;
   319→  const healthcare = healthcareRaw * 100;
   320→
   321→  // Geometric mean
   322→  const indicators = [qol, survivalScore, healthcare];
   323→
   324→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   325→  for (let i = 0; i < indicators.length; i++) {
   326→    if (isNaN(indicators[i])) {
   327→      console.error(`❌ NaN in Development indicator ${i} at month ${state.currentMonth}`);
   328→      console.error(`   qol: ${qol}, survivalScore: ${survivalScore}, healthcare: ${healthcare}`);
   329→      throw new Error(`NaN in Development paradigm calculation - indicator ${i} is NaN`);
   330→    }
   331→  }
   332→
   333→  const product = indicators.reduce((acc, val) => {
   334→    const floored = Math.max(val, MIN_FLOOR);
   335→    return acc * (floored / 100);
   336→  }, 1);
   337→
   338→  const result = Math.pow(product, 1 / indicators.length) * 100;
   339→
   340→  // Final NaN check
   341→  if (isNaN(result)) {
   342→    console.error(`❌ NaN result in Development calculation at month ${state.currentMonth}`);
   343→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   344→    throw new Error(`Development geometric mean produced NaN - check calculation`);
   345→  }
   346→
   347→  return result;
   348→}
   349→
   350→/**
   351→ * Calculate Ecological paradigm score from simulation state
   352→ *
   353→ * UPDATED (Oct 21, 2025 - FIX #14): Uses progressive recovery scoring system
   354→ * - Replaces binary breach counting with impact-weighted recovery progress
   355→ * - Gives credit for partial recovery before full boundary un-breach
   356→ * - Research-backed weights based on mortality potential
   357→ *
   358→ * Indicators:
   359→ * - Planetary Boundaries (50%): Progressive recovery score (0-100)
   360→ * - Resource Depletion (25%): 100 - resourceDepletion
   361→ * - Climate Stability (15%): 100 - (temperatureAnomaly / 2.0) * 100
   362→ * - Pollution (10%): 100 - pollutionLevel
   363→ *
   364→ * SCORE INTERPRETATION (Empirically Realistic, FIX #14):
   365→ * - **0-10 (Catastrophic Collapse):**
   366→ *     Most/all boundaries breached, cascades active, mass mortality
   367→ *     Expected frequency: 15-25% of runs
   368→ *
   369→ * - **10-30 (Stabilized):**
   370→ *     Boundaries still breached but not worsening, technologies deployed,
   371→ *     emissions declining but ecosystem damage persists
   372→ *     Expected frequency: 40-50% of runs (MOST REALISTIC OUTCOME)
   373→ *     This is NOT dystopia - represents sustainable development path
   374→ *
   375→ * - **30-60 (Recovering):**
   376→ *     Some boundaries un-breached, partial restoration underway,
   377→ *     sustained net-negative emissions, slow healing
   378→ *     Expected frequency: 25-35% of runs
   379→ *     Requires 10-30 years sustained action post-net-zero
   380→ *
   381→ * - **60-100 (Restored):**
   382→ *     Most boundaries safe, ecosystem resilience restored,
   383→ *     full environmental health achieved
   384→ *     Expected frequency: 5-10% of runs (HEROIC ACTION + 50-100 YEARS)
   385→ *     Requires 50-100 years sustained effort beyond simulation timeframe
   386→ *
   387→ * CRITICAL: 10-30/100 is NOT failure - it's empirically realistic stabilization.
   388→ * Full restoration (60-100) takes 50-100 years beyond most simulation runs.
   389→ *
   390→ * @param state - Current game state
   391→ * @returns Ecological score (0-100)
   392→ */
   393→function calculateEcological(state: GameState): number {
   394→  const MIN_FLOOR = 0.1;
   395→
   396→  // Planetary Boundaries: Use progressive recovery scoring (Oct 21, 2025)
   397→  // Replaces simple binary breach counting with impact-weighted recovery progress
   398→  const { calculateProgressiveEcologicalScore } = require('../../planetaryBoundaryRecovery');
   399→  const boundariesScore = calculateProgressiveEcologicalScore(state);
   400→
   401→  // Resource Reserves (0-1 → 0-100)
   402→  if (state.environmentalAccumulation?.resourceReserves === undefined) {
   403→    throw new Error('❌ state.environmentalAccumulation.resourceReserves is undefined in calculateEcological:320 - initialization bug');
   404→  }
   405→  const resourceReserves = state.environmentalAccumulation.resourceReserves;
   406→  const resourceScore = resourceReserves * 100;
   407→
   408→  // Climate Stability (0-1 → 0-100)
   409→  if (state.environmentalAccumulation?.climateStability === undefined) {
   410→    throw new Error('❌ state.environmentalAccumulation.climateStability is undefined in calculateEcological:324 - initialization bug');
   411→  }
   412→  const climateStability = state.environmentalAccumulation.climateStability;
   413→  const climateScore = climateStability * 100;
   414→
   415→  // Pollution (0-1 → 100-0, inverted)
   416→  if (state.environmentalAccumulation?.pollutionLevel === undefined) {
   417→    throw new Error('❌ state.environmentalAccumulation.pollutionLevel is undefined in calculateEcological:328 - initialization bug');
   418→  }
   419→  const pollutionLevel = state.environmentalAccumulation.pollutionLevel;
   420→  const pollutionScore = (1 - pollutionLevel) * 100;
   421→
   422→  // DEBUG: Log when any value is problematic
   423→  if (state.currentMonth % 12 === 0 || isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore)) {
   424→    const hasNaN = isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore);
   425→    if (hasNaN || state.currentMonth === 168) {
   426→      console.log(`\n🔍 ECOLOGY DEBUG (Month ${state.currentMonth}):`);
   427→      console.log(`   boundariesScore: ${boundariesScore} (${isNaN(boundariesScore) ? 'NaN!' : 'ok'})`);
   428→      console.log(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   429→      console.log(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   430→      console.log(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   431→    }
   432→  }
   433→
   434→  // Geometric mean
   435→  const indicators = [boundariesScore, resourceScore, climateScore, pollutionScore];
   436→
   437→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   438→  for (let i = 0; i < indicators.length; i++) {
   439→    if (isNaN(indicators[i])) {
   440→      console.error(`❌ NaN in Ecological indicator ${i} at month ${state.currentMonth}`);
   441→      console.error(`   boundariesScore: ${boundariesScore}`);
   442→      console.error(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   443→      console.error(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   444→      console.error(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   445→      throw new Error(`NaN in Ecological paradigm calculation - indicator ${i} is NaN`);
   446→    }
   447→  }
   448→
   449→  const product = indicators.reduce((acc, val) => {
   450→    const floored = Math.max(val, MIN_FLOOR);
   451→    return acc * (floored / 100);
   452→  }, 1);
   453→
   454→  const result = Math.pow(product, 1 / indicators.length) * 100;
   455→
   456→  // Final NaN check - if this triggers, the bug is in geometric mean calculation
   457→  if (isNaN(result)) {
   458→    console.error(`❌ NaN result in Ecological calculation at month ${state.currentMonth}`);
   459→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   460→    throw new Error(`Ecological geometric mean produced NaN - THIS IS THE BUG WE FIXED!`);
   461→  }
   462→
   463→  return result;
   464→}
   465→
   466→/**
   467→ * Calculate Indigenous paradigm score from simulation state
   468→ *
   469→ * Indicators:
   470→ * - Social Trust (40%): state.socialCohesion.trust
   471→ * - Community Bonds (40%): state.socialCohesion.communityBonds
   472→ * - Meaning Crisis (20%): 100 - meaningCrisis (inverted)
   473→ *
